local _, WFJ = ...
WFJ.Data.add("quest", {
  [98013] = { "膨れ上がる軍勢", "Grove of the AncientsにいるArbalのために、Stormscale Myrmidonを$N1体、Stormscale Sorceressを$N2体、Stormscale Warriorを$N3体倒してください。", "廃墟で過ごす時に備えて、心を引き締めなさい、若き者よ……あそこでは自由に通してはもらえません。\n\n呪われたHighborne、今はnagaと呼ばれる者たちが、かつての偉大な都を大勢うろついています。北東へ旅し、彼らをこの地から排除しなさい。\n\n彼らがかつてそうであったものは……もはやありません。もし彼らがTwilight's Hammerに手を貸しているなら、かつて自分たちをかくまってくれた森に、さらなる苦しみをもたらすことしかできないでしょう。\n\n彼らが求めているのは戦です、{class}。戦……それこそが、私たちがもたらすものです。", nil, nil, 0xae8b4fd3, 0x2a0b423f, 0x83d7b2a0, nil, nil, "...mm" },
  [98021] = { "Sentinel Hillへの旅", "WestfallのSentinel HillにいるGryan Stoutmantleに報告してください。", "この世界で何か善いことを始めたいなら、南のWestfallにある、Sentinel Hillと呼ばれる集落のGryan Stoutmantleという男のもとへ出向くことを勧める。彼の民は助けを必要としている。\n\n別の次元からここへ旅してきたあなたには、我々の土地が直面している問題は小さく見えるかもしれない。だが断言しよう、そうした問題に苦しむ人々にとって、あなたの助けはすべてを意味する。そしてあなたはその働きによって強くなるだろう。\n\n幸運を祈る、冒険者よ！", nil, nil, 0xc1c4216f, 0x617304a7, 0x0210f242, nil, nil, "...mm" },
  [98024] = { "Crossroadsへの旅", "The BarrensのThe CrossroadsにいるThorkに報告してください。", "精霊界からここへ旅してきたあなたには、我々の土地が直面している問題は小さく見えるかもしれない。だが安心してほしい、Hordeが直面している危険はまぎれもなく本物だ。務めを生き延びれば、あなたは手強い存在になるだろう。\n\nこの世界で何か善いことを始めたいなら、南西へ旅して、Barrensと呼ばれる広大な土地へ行くといい。そこにCrossroadsと呼ばれる集落がある。そこの誇り高き住民たちは、常に助けを必要としている。\n\n名誉と共に行け、冒険者よ！", nil, nil, 0xeac1fba3, 0x0ce1d543, 0x7fd58f06, nil, nil, "...mm" },
  [98025] = { "お尋ね者：Jai'vhanel", "Jai'vhanelと呼ばれるフクロウを見つけて倒し、その羽根を一枚手に入れてください。その黒いフクロウは、Ameth'Aranの遺跡の北、山のふもと付近で最後に目撃されています。Jai'vhanelを倒したことを、AuberdineのSentinel Glynda Nal'Sheaに報告してください。", "告知！\n\n「Swordfeather」とも呼ばれる梟、「Jai'vhanel」の討伐に報酬が出されている。\n\n残念ながら、この梟は狂ってしまい、Auberdine付近の道を行く旅人を襲い始めた。\n\nJai'vhanelが最後に目撃されたのは、Ameth'Aranの遺跡の北、山のふもとである。討伐の証として、その漆黒の羽根を1本持ち帰ること。\n\nこの懸賞金の請求は、AuberdineのSentinel Glynda Nal'Sheaまで。\n\nAuberdine Village Council", nil, nil, 0x85ab0f27, 0x9af9befe, 0xaa520644, nil, nil, "..smm" },
  [98027] = { "Gleaming Crescent Necklace", "Crescent NecklaceをAstranaarのMaliynnに届けて下さい。", nil, nil, nil, 0xb3215af6, 0x8ae5ee49, nil, nil, nil, "..mmm" },
  [98028] = { "Baron Marinous", "Clouded Water GlobeをDarkshoreのGrove of the AncientsにいるOnuに届けてください。", "強大なエレメンタルに残されたのは、得体の知れない何かに濁った、純粋な水と思われる球だけだ。球の縁は澄んで見えるのに、回してみると、まるで濁りが中を覗かせまいと積極的に邪魔しているかのようだ。\n\nそれに何が起きたにせよ、そしてそれが守っていた遺跡に何が起きたにせよ、その何かはまだ何らかの形で働き続けている。\n\n遥か南のGrove of the Ancientsにいる、Ancient of LoreのOnuだけが、もっと知っている可能性がある。", nil, nil, 0x9d32a10a, 0xd906839f, 0x53a26984, nil, nil, "...mm" },
  [98042] = { "遊びのうちはいいけれど……", "DarkshoreのMaster's GlaiveにいるTwilight DiscipleかThugからPeerless Eyeを手に入れ、Auberdineでそれを引き取ってくれる人物を見つけてください。", "<Twilight Tomeから1枚きりのページを破り取ると、不吉な声が招かれもせずに頭の中にあふれ込んでくる。>\n\n彼らは失敗した。\n\nお前は忘れ去られるだろう。\n\n彼らは手に入れた目を失うだろう。", nil, nil, 0x780af214, 0x29e68b4e, 0x10cc5e5e, nil, nil, "...mm" },
  [98046] = { "大地の冠", "Drained VesselをDarnassusのTemple of the MoonにいるLariiaに届けてください。", "<Arch Druid Fandral Staghelmの目が細められる。>\n\nまだいたのか？\n\nその小瓶を持って、私の前から消えろ、{class}。私の答えが水の中にないことは明らかだ。以前もそうではなかったように。\n\n南のTemple of the Moonにいる女司祭の誰かが、処分してくれるかもしれん。\n\n<Fandralは目をそらし、もうあなたには話しかけない。>\n\nこれを成し遂げるには、他を当たらねばならん……", nil, nil, 0x6a9c354f, 0xfa735665, 0x87e3b8dc, nil, nil, "...mm" },
  [98059] = { "Hillsbradの蓄え", "渡されたSealed Company Requestを、Hillsbradの町役場にある帳簿台の上に置いて下さい。", nil, nil, nil, 0x741522bc, 0xd8226166, nil, nil, nil, "..mmm" },
  [98065] = { "大地の冠", "Moonwell RemnantsをDarnassusのTemple of the MoonにいるTyrande Whisperwindに届けてください。", "これを今すぐTyrandeのもとへ届けなければなりません！ もっと儀式にふさわしい器に移してあげましょう。\n\n恐れることはありません。High Priestess of Eluneは厳格ですが、お優しい方です。Darnassusに入るすべての者を守り、私たちの女神の光をすべての者にもたらしておられます。\n\nこの聖なる水を喜んで受け取ってくださるでしょう。この真上におられますよ。", nil, nil, 0x6a9c354f, 0x283abfd9, 0x13bb30c2, nil, nil, "...mm" },
  [98067] = { "Sentinelの目", "DarnassusのTemple of the MoonにいるSentinel Dalia Sunbladeのために、Cenarion Holdの深部の入口、Darnassus Bank、Craftsman's Terrace Inn、City GateにSentinel Owlsを設置してください。", "General Feathermoonは、すべての歩哨がEluneに祈る時間を持てるよう取り計らっています。真の女狩人が振るうのは刃だけではなく、敵を打ち破るための女神の賜物でもあるのです。\n\n私の日々の務めを手伝ってもらえますか。街のあちこちに歩哨を配置してください。まずは北のCenarion Holdの下へ続くトンネル、町の中心の銀行、北東のCraftsman's Terraceの宿屋、そして街の門です。衛兵たちが手を貸してくれるでしょう。\n\nTeldrassilで何かがおかしい……私たちは警戒を怠ってはなりません。", nil, nil, 0xf4253869, 0xe7a28828, 0x37765008, nil, nil, "...mm" },
  [98069] = { "Stolen Freewind Supplies", "Stolen Freewind Suppliesを8個、Freewind PostのJandiaのところへ持って行って下さい。", nil, nil, nil, 0x02f16acd, 0xcd999837, nil, nil, nil, "..mmm" },
  [98070] = { "金切り声を止める", "Screeching Harpiesを$N1体、Screeching Roguefeather Harpiesを$N2体、Screeching Windcaller Harpiesを$N3体倒して下さい。", nil, nil, nil, 0x6fb557e1, 0x9dc5d06f, nil, nil, nil, "..mmm" },
  [98071] = { "醸造家の取引", "Fallrook VarietalのボトルをHillsbrad Foothills南東のDun Garokに届け、彼らのHomebrew Hopsを一袋持ち帰って下さい。", nil, nil, nil, 0xdbd8fe1c, 0xad567a8c, nil, nil, nil, "..mmm" },
  [98072] = { "空のワニ", "Pristine Crimson Scaleを8枚集め、Menethil HarborのJames Halloranのところへ持って行って下さい。", "あんたは本当にやり手だな! もう一つだけ頼みがあるんだ。ちょっと危ないことでも平気ならだけどね。\n\ncrocoliskの商売は安定した稼ぎになるけど、whelpの鱗が生む金に比べたら小物さ。あれなら袋一つに大枚をはたく連中がいるんだ。\n\n空のワニって俺は呼んでるのさ! 弟子にはとても取ってこられないけど、あんたにはうってつけだろう!\n\nwhelpは東のずっと先、Green Belt沿いにいる。でも気をつけてな、あの丘には厄介なオークがいるから!", nil, nil, 0x3db2cf68, 0xba342fd8, 0x793428d8, nil, nil, "...mm" },
  [98093] = { "片付けるべき畑", "Barrens南部にいるSulhasaは、安全に木から降りられるよう、このあたりのStormhide lizardを$N1匹とHecklefang Stalkerを$N2体片付けてほしいと言っています。", "見つけてくれて本当によかった！\n\n今朝はとてもいい天気だったから、Camp Taurajoから黄金の道を歩いて下ってきたの。帰る時間になったら帰れなくなっちゃって……ハイエナの群れがぐるぐる回り始めて、Stormhideのトカゲが唯一の逃げ道をふさいだのよ。\n\n慌ててこの木によじ登ったんだけど、この時間は敵が多すぎて、野原を突っ切って家まで走って帰れないの。\n\nこのStormhideとHecklefang Stalkersを追い払ってもらえないかしら？", nil, nil, 0x08f3d4db, 0x04fff6f2, 0x872fbe59, nil, nil, "...mm" },
  [98094] = { "斥候の支援", "High Executor Darthaliaは、Tarren Millの南、Dun Garokの外にいるDeathstalker Masojに新しい命令を届けてほしいと言っています。", "前線の密偵に重要な情報を届けるのを任せられると分かった今、お前に追加の任務がある。\n\nこれをほぼ真南にいるDeathstalker Masojへ届けろ。向こうに着いてこれを渡せば、奴がさらに仕事を与えるだろう。奴はNethander Steadと呼ばれる腐ったブドウ園の北、小高い場所に配置されている。\n\nこの地を支配する我々の計画は着実に進んでいる。", nil, nil, 0x7440188e, 0x30f9063e, 0xb2d0b01d, nil, nil, "...mm" },
  [98095] = { "貴重な見晴らし台", "Deathstalker Masojは、Apothecary Vialsを3本、Hillsbrad Foothills周辺の山頂に置いて、彼のところへ戻ってきてほしいと言っています。", "我らの最高司令部は、コウモリの乗り手を使って戦略部隊を送り込んでいる。丘陵の要所で合図の灯が失われてしまった。\n\nこのvialsを持っていけ。3か所で栓を抜くのだ。Dun Garokに接する丘、Dunholde Keepを見下ろす台地、そして最後はHillsbradの町の上にあるHeadlandの尾根だ。立ちのぼる蒸気は、コウモリの感覚にとって強力な音叉のように働き、再び目的の降下地点へ奴らを引き寄せるだろう。\n\n砕けた空の小瓶を探し、我々の目印を新しくしてくれ。", nil, nil, 0x9e9c3c95, 0xa522d3ad, 0x215c740c, nil, nil, "..smm" },
  [98155] = { "Pristine Pesterhide Pelts", "Pristine Pesterhide Peltを$N1枚、Kristy Grantのところへ持って行って下さい。", nil, nil, nil, 0x5f2a26ec, 0x5d7bef18, nil, nil, nil, "..mmm" },
  [98156] = { "梱包された極上の毛皮", "Package of Pristine PeltsをKimberly Grantのところへ持って行って下さい。", nil, nil, nil, 0x702cae31, 0x518a3bbe, nil, nil, nil, "..mmm" },
  [98189] = { "Statuetteを返す", "Menethil StatuetteをMenethil KeepのCaptain Stoutfistに届ける。", "なんてこった、これは……これは美しい!\n\nBlind Princessは、悲劇が起きる前にこれをMenethil Harborへ届けるはずだったんだ。あと少しだったのに!\n\nたしか、すぐ後ろのMenethil KeepにいるCaptain Stoutfistが受け取りのサインをすることになっていたはずだ。お前が仕事の締めくくりをしてみないか?", nil, nil, 0x6359787c, 0x0c8c34af, 0x67af9a56, nil, nil, "...mm" },
  [98190] = { "一家の友", "Menethil StatuetteをStormwind KeepのHighlord Bolvar Fordragonに届ける。", "こいつはすぐにStormwindへ持って行ったほうがいい。この砦と港がKing Terenas Menethil IIの名を冠していることは誇りだが、ここは敵という酷い嵐の中の穏やかな港にすぎん。ここは安全じゃないんだ。\n\n特にDragonmawは、こういうものを奪うためなら多くを犠牲にするだろう……奴らがこれで何をするかと思うと身震いがする。\n\nこの件は指揮系統を順に上がっていく必要はないぞ、若いの。これを持ってまっすぐHighlord Fordragonのところへ行け。どこに保管するのが一番いいか、あの方なら分かるはずだ。", nil, nil, 0xd13a5ecd, 0xb560772b, 0xcc6c0655, nil, nil, "...mm", nil, nil, 0x8176cdb8, nil, nil },
  [98191] = { "一家の友", "Menethil StatuetteをCathedral of LightのLord Grayson Shadowbreakerに届ける。", nil, nil, nil, 0xd13a5ecd, 0x89dd523c, nil, nil, nil, "..mmm" },
  [98197] = { "戦利品", "Valstag Ironjawのために、Menethil HarborからKhaz Modan Timberを$N1個とKhaz Modan Ironを$N2個取り戻してください。", "この港は、もともとOld HordeがHillsbradへの海からの侵攻の足場として築いたものなんだ。Lordaeronの守りを完全に出し抜いたんだよ！\n\nたくさんの命が失われた……\n\nさらにひどいことに、その艦隊はまさにKhaz Modanから奪った資源で造られたんだ！\n\nAdmiral Proudmooreがあの野蛮人どもを蹴散らしてAllianceのためにここを築いた後も、その多くが港に残っている。Dragonmawが動き出した今、町の守りを固めるのにそれが必要になるんだ。", nil, nil, 0x39128c53, 0xed2e4170, 0xa2e5a960, nil, nil, "...mm" },
  [98208] = { "天の花", "Menethil HarborのSylessa DuskwhisperのためにNord'elを取り戻して下さい。", "私は大樹Teldrassilの地、AuberdineからこのMenethil Harborへ来ました。我が民にとって大切な花を取り戻すためです。\n\n我が民の船Flying Ospreyは、Kul Tiran Third Fleetと行動を共にして、幾月も前にここで難破しました。積み荷の中には、Nord'el、あなたがたの言葉でいう「Bloom of the Heavens」として知られる花がありました。かつての我らの故郷、Mount Hyjalの頂で満月の下に咲いた花です。\n\nどうか取り戻すのを手伝ってください！残骸は街のすぐ南にありますが、獰猛なmurlocの略奪者たちが棲みついているのです！", nil, nil, 0x67289a3e, 0x145af630, 0xc0d3a012, nil, nil, "...mm" },
  [98209] = { "天の花", "Nord'elをDarkshoreのAuberdineにいるThundris Windweaverのところへ持って行って下さい。\n\nMenethil Harborから出る船でそこへ行けると、Sylessaが言っていたのを思い出す。", nil, nil, nil, 0x67289a3e, 0x740a8c63, nil, nil, nil, "..mmm" },
  [98216] = { "我らの現在を理解する", "Goaz Warderの近くでGoaz Stoneを使い、そのTitanic KeystoneをProspector Whelgarのところへ持ち帰って下さい。", nil, nil, nil, 0x58a10f76, 0xbfb2440c, nil, nil, nil, "..mmm" },
  [98219] = { "面目を失った副官", "Hillsbrad FoothillsのSouthshoreにいるLieutenant Farren Orinelleと話す。", "statuetteを無事に届けてくれたこと、改めて礼を言う、{name}。\n\n別のことでも君の助けを借りたい。市の衛兵の一人が、Hillsbrad FoothillsのSouthshoreでの任務に配置換えになった。\n\n彼の父は私の友人でね。あいつにはいい教訓になるだろうという考えに異論はないが……それでも成功してほしいのだ。君のような者が手を貸してくれれば、彼にとって大いに助けになるだろう。\n\nもしまた通りかかるなら、Menethil Harborからそちらへ渡る船がある。", nil, nil, 0xc567588f, 0x4c7ba953, 0xc1f837e2, nil, nil, "...mm" },
  [98221] = { "灰の中から", "Menethil KeepのCaptain Stoutfistは、Angerfang Encampmentにある4組のAttack Plansを破棄してほしいと言っています。", nil, nil, nil, 0x08a75e96, 0x18b3d712, nil, nil, nil, "..mmm" },
  [98223] = { "古い習慣", "Tattered SpellbookをMenethil HarborのCaptain Stoutfistのところへ持って行って下さい。", nil, nil, nil, 0x75c9f241, 0x3bf963b0, nil, nil, nil, "..mmm" },
  [98230] = { "この地は彼らの地だった", "Menethil Harborの東、道沿いにいるHowin Kindfeatherを見つけて下さい。", nil, nil, nil, 0x5ef5a781, 0x920b4ded, nil, nil, nil, "..mmm" },
  [98240] = { "Crimson Crateの配達", "Crimson CrateをMenethil Harborの東、街道から少し外れたところにいるHowin Kindfeatherに届ける。", "whelpの話はもう公に広まったぜ、{name}。さっそく注文が入ったんだ!\n\n俺がきれいに包んでおくから、あんたはそれを客のところへ運んでくれ。分かってる、分かってるって。これが本当に最後の頼みだ、約束する!\n\n届け先は「Howin Kindfeather」って奴だ。よりによって自分のgryphonに手紙を持たせて町によこしてきたんだよ! 東の街道から少し外れたところ、Whelgar's Excavation Siteを少し過ぎたあたりにいるそうだ。知ってるならな。", nil, nil, 0xed839e17, 0xdfb38dba, 0x708169ee, nil, nil, "...mm" },
  [98245] = { "Razormawをつつく", "Howin KindfeatherのためにRazormaw Incisorを$N1本集めて下さい。", nil, nil, nil, 0x3df51a68, 0x27f4ab42, nil, nil, nil, "..mmm" },
  [98246] = { "試練の時", "Howin KindfeatherのためにPerfect Razormaw Eggを$N1個集めて下さい。", nil, nil, nil, 0x488226eb, 0x110e549b, nil, nil, nil, "..mmm" },
  [98247] = { "Shipping Label", "Shipping Labelを、Redridge MountainsにあるAzeroth Commerce Authorityの交易拠点にいる誰かに届けてください。", "<すっかり中身の詰まった木箱の側面に、破れた荷札が見つかる。本来の宛先は破り取られているが、出どころの詳細はまだ残っている。\n\n「Azeroth Commerce Authority所有。空の木箱や未配達の荷物は、Redridge MountainsのThree Cornersの交差路にある当地の交易拠点までご返却ください。配達人には時間と移動に対する報酬が支払われます。」\n\n文字の横には、その送り先付近の地域を描いた雑な地図がある。>", nil, nil, 0xe6d6b8f1, 0x2c55cb98, 0x6fa4ac5c, nil, nil, "...mm" },
  [98248] = { "Shipping Label", "Shipping Labelを、BarrensのCrossroads付近にあるDurotar Supply and Logisticsの交易拠点にいる誰かに届けてください。", "<すっかり中身の詰まった木箱の側面に、破れた荷札が見つかる。本来の宛先は破り取られているが、出どころの詳細はまだ残っている。\n\n「破損した荷物や空の木箱は、BarrensのCrossroadsの真西という便利な場所に移転したDurotar Supply and Logisticsの交易所までご返却ください。皆さまの時間は貴重です。そのご尽力には報酬をお支払いします！」\n\n文字の横には、その送り先付近の地域を描いた雑な地図がある。>", nil, nil, 0xe6d6b8f1, 0x6b4c68ba, 0xdcdf21c0, nil, nil, "...mm" },
  [98251] = { "二度と戻らない", "Shadowhorn Stagを$N1体とAshenvale Bearを$N2体倒し、Fallen Sky Lakeの北西にいるVa'xug Firefureのところへ戻る。", "があああっ!\n\n腹が立って仕方ない。Ashenvaleは道が分かりやすいって言われたのに。誰にとって分かりやすいのさ? 獣? 鳥?\n\nついさっきまで薬草を摘んでいたのに、次の瞬間にはこの谷底に閉じ込められてる。ほんのさっき立っていた場所に戻るのに、本当に森を半周もしなきゃならないわけ?\n\nこうなると、私の呪文は不安定になって……おかしな振る舞いをするんだ。\n\n近くの野生動物を減らしてくれない? あいつらの間抜けな蹄の音すら癇に障る。この呪われた森が大嫌い。", nil, nil, 0xda72cb7d, 0x793d1806, 0xd2c43c4c, nil, nil, "...mm" },
  [98252] = { "虚無の道", "Va'xugのEye of KilroggにAshenvaleの本道へ戻る道を示して下さい。", "俺のEye of Kilroggに、この峡谷を抜けてAshenvaleの道へ戻るルートを示してくれ。止まらずに進ませろ。道が開けたと分かれば、俺も後を追う。\n\n俺はここに残る。どちらか一人は方角を見失わずにいるべきだ。お前が道に迷ったら、眼を通して戻る道を導いてやれる。この悪意に満ちた森で、二人揃って盲目のまま彷徨うのはごめんだ。\n\n詠唱を保てるのは4分だ。それ以上は無理だ。幻視が途切れる前に道へたどり着くか、俺のところへ戻ってやり直すかだ。", nil, nil, 0x9e802cef, 0x41338fb7, 0xbaa5cde3, nil, nil, "...mm" },
  [98282] = { "錬金術の危険物", "Menethil HarborのCaitlin Grassmanのために、Thelgen RockでUnruptured Stalker Glandを手に入れてください。", "錬金術の調合の中には、その、とっても危険な場所から材料を取ってこなきゃならないものがあるのよ。しかも、それがただの基本の薬草だったりするの！ ほかの材料はもっとひどいわ！\n\nまた出かける前に、抗毒剤をもっと作らなきゃならないの。この沼のものは何でもかんでも毒があるんだから。まるで土地そのものに毒が流れてるみたい！\n\n手伝ってもらえる？ 遥か南東のThelgen Rockにいる蜘蛛の毒腺がひとつ必要なの。でも破れていないものじゃないとだめ。そうじゃないと、ここに持ってくる前に毒が漏れすぎちゃうから。ごめんね！", nil, nil, 0x67b679f7, 0xac87cb29, 0xd937715e, nil, nil, "...mm" },
  [98283] = { "Carnage", "Carnage's HeadをThe Green BeltのRethiel the Greenwardenのところへ持って行って下さい。", nil, nil, nil, 0x77d7998b, 0x5b85ca0c, nil, nil, nil, "..mmm" },
  [98284] = { "キャンプ101：Enchanting", "スキルの熟練を示したら、Shen'dar VillageのNasalanna Windsingerと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "エンチャンターはなんでもより良くしてくれるし、荒野の野営地ならどこでも歓迎されるもんだ。\n\n野営地用のEnchanted Luteの作り方を教えてくれる奴を知ってるよ。暇な時間に楽しみを見つけるのはすごく大事なことでね、この魔法の品があれば、またほこりっぽい旅路に出た時、どんな困難にも耐えられるようにしてくれるさ。", nil, nil, 0x2e9b8c15, 0xb70a277c, 0xb4a29ffc, nil, nil, "...mm" },
  [98285] = { "キャンプ101：Engineering", "スキルの熟練を示したら、Shadowgale ForestのStrange Hermitと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "エンジニアはいつだって工夫に富むものだし、荒野にひとりでいる時に自分の技を活かせるってのはいいことだ。役に立つ装置のいくつかもない野営地なんて、いい野営地とは言えないからな！\n\nそうそう、エンジニアとして少し経験を積んだらまた会いに来てくれ。特別なものの作り方を教えてやれるからな！", nil, nil, 0x1cb4025b, 0x164e6328, 0xfb7e88ff, nil, nil, "...mm" },
  [98286] = { "キャンプ101：Enchanting", "スキルの熟練を示したら、Shen'dar VillageのNasalanna Windsingerと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "エンチャンターはなんでもより良くしてくれるし、荒野の野営地ならどこでも歓迎されるもんだ。\n\n野営地用のEnchanted Luteの作り方を教えてくれる奴を知ってるよ。暇な時間に楽しみを見つけるのはすごく大事なことでね、この魔法の品があれば、またほこりっぽい旅路に出た時、どんな困難にも耐えられるようにしてくれるさ。", nil, nil, 0x2e9b8c15, 0xb70a277c, 0xb4a29ffc, nil, nil, "...mm" },
  [98287] = { "キャンプ101: Engineering", "技能の熟練を示したら、StormwindのSprite Jumpsprocketと話し、自分の職業のキャンプ用品の作り方を学ぶ。", "あんたみたいなエンジニアは、楽しみと儲けのために、ありとあらゆる部品やボットや爆弾をこしらえられる。\n\nあんたのキャンプ用にReagent Botの作り方を教えられる奴を知ってると思うぜ。この便利な自動人形がいれば物資が十分に保たれるから、あんたも仲間も、呪文の燃料になる材料を切らすことはないってわけさ。", nil, nil, 0x1cb4025b, 0xba6c8a24, 0x549b28c0, nil, nil, "...mm" },
  [98291] = { "Dragonmawに死を", "Howin Kindfeatherのために、Dragonmaw RetreatでDragonmaw Reclaimerを$N1体、Dragonmaw Soulbinderを$N2体、Dragonmaw Infiltratorを$N3体倒して下さい。", nil, nil, nil, 0xa1aa470d, 0x3d74e20a, nil, nil, nil, "..mmm" },
  [98293] = { "強制的な武装解除", "Dragonmaw RetreatでDragonmaw Armamentsを$N1個集め、Menethil KeepのCaptain Stoutfistのところへ持って行って下さい。", nil, nil, nil, 0xe87e8bcf, 0xa648dc25, nil, nil, nil, "..mmm" },
  [98297] = { "循環を断つ", "Howin Kindfeatherのために、Dragonmaw GatesでSubdued Dragonspawnを倒して下さい。", nil, nil, nil, 0xf76afbec, 0x67d75546, nil, nil, nil, "..mmm" },
  [98298] = { "Arugalの愚行", "Worgen Bitsを$N1個、The SepulcherにいるDalar Dawnweaverのところへ持って行ってください。", "ああ、すべてが恥ずかしいほどはっきりしました！ Arugalにはほとんど魔力などなかったのです。ましてやworgenを生み出すほどのものなど。「Arugal's Curse」ですって。ふん！ ほんの数秒もつのがやっとの効き目ですよ。\n\nこの枷は、彼が獣を縛れても生み出せはしないことの証です。worgenは明らかに別の方法で呪いを広めたのです。私はその方法を知りたい。\n\n南のGreymane Wallへ行きなさい。worgenは近くの人間に広がりつつあるようです。獣どもを引き裂いて、見つけたものを何でも持ってきなさい。これにはもっと直接的なやり方が必要です。", nil, nil, 0x93f7323d, 0x865fabf6, 0x0e0f701a, nil, nil, "...mm" },
  [98299] = { "拡大の阻止", "The SepulcherにいるDalar Dawnweaverのために、Sickly Refugeeを$N1人とHaggard Refugeeを$N2人倒してください。", "ひとつだけわかっていることがあるとすれば、Silverpineのworgenの原因がArugalだということです。彼自身の企みであれ、そうでないにしろ。わからないのは、それがどう広がるかです。\n\n私が呪いを止める方法を研究するあいだ、最優先すべきはそれを封じ込めることです。この病はForsakenには感染しないようですが、大勢の人間がGreymane Wallのそばに集まっています。\n\n壁へ行き、Arugalの僕となる前にその難民たちを始末しなさい。それと、噛まれないようにね、{race}。", nil, nil, 0x030f1fc2, 0x16b6b162, 0xef81af04, nil, nil, "...mm" },
  [98300] = { "Ironforgeへの知らせ", "Howin's MissiveをIronforgeのKing Magni Bronzebeardに届けて下さい。", nil, nil, nil, 0x70a6616f, 0x4ae70287, nil, nil, nil, "..mmm" },
  [98310] = { "我らの未来を探る", "Ados、Modr、Golm、Neruの近くでGoaz Stoneを使い、それらの心臓をProspector Whelgarのところへ持ち帰って下さい。", nil, nil, nil, 0x9ceacfd8, 0xe9da4d7c, nil, nil, nil, "..mmm" },
  [98313] = { "さらなる研究のために", "Whelgar Relic PackageをIronforgeのHistorian Karnikのところへ持って行って下さい。", nil, nil, nil, 0x89f4c96b, 0x0134cc07, nil, nil, nil, "..mmm" },
  [98319] = { "山の確保", "Mountaineer Gretchenのために、Grizzled DenでMountaineer Corneliusを見つけてください。", "トロールの問題があるだけでも十分ひどいってのに、山にはwendigoがあふれ返っとる！ 普段は自分たちの洞窟にこもっとるんだが、兎みたいに増えとるらしい。今じゃここから北のGrizzled Denまで埋め尽くしとる。\n\nWhitebeardの報告書が欲しけりゃ、相棒のCorneliusを見つけにゃならん。あの石頭、ちょいと興奮しすぎて頭から突っ込んでいきおった。勇敢だが、馬鹿だ。\n\n洞窟に入って、奴がどこにおるか見てきてくれ。ついでに獣どもを何匹か片づけてくれてもかまわんぞ。", nil, nil, 0xe669cbf4, 0xd8ab5017, 0xf9d641d5, nil, nil, "..smm" },
  [98321] = { "Flintfire's Shipment", "KharanosにいるTongus Flintfireのために、Grizzled DenからFlintfire Shipmentを$N1個集めてください。", "ほっほう！ 手を汚すのを怖がらん{race}に会えるとはいいことだ。\n\n仕事を探しとるなら、あいにく今はちょいと物資が足りなくてな。一番頼りになる鉱石の出どころがwendigoに占拠されちまって、洞窟は放棄されちまった。鉱夫たちは逃げる時に何もかも置いてきちまったんだ！\n\nそうだ、西のGrizzled Denをちょいと覗いて、なくなった荷を見つけられんか見てきてくれんか？ そうしてくれりゃ、わしらの手間が大いに省けるんだが。", nil, nil, 0xc0b8d385, 0xffee5126, 0xa4bbc762, nil, nil, "...mm" },
  [98322] = { "山の確保", "Kharanosの西にいるMountaineer Gretchenの様子を見に行ってください。", "暗い洞窟の探検は冒険者の仕事だ。わしの仕事は報告書を書いてIronforgeへ送ることだけでな。\n\n困ったことに、わしの報告の一つが……まあ、戻ってこんのだ。何人かの山岳兵に、このあたりのwendigo問題をもっと調べるよう頼んだんだが、音沙汰がない。\n\nどうせそのへんを出歩くんなら、町のすぐ西にいるMountaineer Gretchenの様子を見てきてくれんか。わしはもう十分遅れとるんだ！", nil, nil, 0xe669cbf4, 0x7154065a, 0x8d18d3fa, nil, nil, "...mm" },
  [98323] = { "山の確保", "Mountaineer Gretchen's ReportをKharanosのSenir Whitebeardに届けてください。", "中にいる間に、あの雑種どもをかなりの数片づけてくれただろうな。Corneliusのことは残念だったが。\n\nお前さんの話からすると、あの洞窟はもう見込みがないということくらいしか報告することはないな。Whitebeardはその答えを気に入らんだろうが、あの死の罠に他の者を送り込む気にはなれん。\n\n遠慮なく伝えてくれ、{name}。わしは山が安全になるまでこの場所を離れんぞ。", nil, nil, 0xe669cbf4, 0x2405aa8a, 0xd096a625, nil, nil, "...mm" },
  [98326] = { "Frosthowl", "Frosthowlを倒し、Brewnall VillageのGretta GanterのためにSack of Fishを手に入れて下さい。", "凍った湖で釣りをするのがどれだけ大変か知っとるかい？ うちの気の毒な亭主のPaxtonは、何日も湖の真ん中に出ずっぱりだってのに、成果といったら袋ひとつがやっとさ。\n\nいや、袋ひとつの成果はあったんだよ。あの忌々しいwendigoがあたしを襲って、獲物を持ち去っちまうまではね。全部釣り直すには何週間もかかる！ そもそも、あの大声のFrosthowlが魚をみんな追い払っちまってなけりゃの話だけどね。\n\n頼むから取り返してきておくれ、いいね？ あのよだれ垂らしの獣は、南東のGrizzled Denの奥深くのどこかに隠れとるよ。", nil, nil, 0x08b6e05f, 0xea44c644, 0xbf80aad5, nil, nil, "...mm" },
  [98340] = { "大いなる猫の霊", "MoongladeのNighthavenの村にいるDendrite Starblazeと話してください。", "あなたは旅の次の段階に進む準備ができたようですね、若きドルイドよ。Dendrite Starblazeがあなたを呼んでいて、もう一度Moongladeで彼を訪ねてほしいと願っています。\n\nMoongladeへ連れていってくれる魔法を呼び出す術はもう身につけていますから、望むならすぐにでも出発できるはずです。ドルイドの修行を続けたいのなら、早めに発つことをお勧めします。", nil, nil, 0xb22fd0a9, 0x127a78ca, 0xe8864144, nil, nil, "...mm" },
  [98341] = { "大いなるWindborneの猫の霊", "Moonglade南部でAvatar of Saeyleenanを探し出し、風に乗る猫の本質に関して何を教えてくれるのか聞いて下さい。", "あなたの故郷の精霊が最近ここに現れ、あなたをそこへ導くよう私に頼んできました。この風をまとう猫の精霊は、あなたがZephrasの精霊の猫の姿をとれるよう、教え導くために来たのです。\n\nすべてのドルイドはいずれこの知恵を求めますが、あなたの故郷の姿は私たちの伝統的なものとは少し違うようです。この精霊の猫の姿をとりたいのなら、私たちの試練を受けなければなりません。\n\n精霊はMoongladeの南部、双子の橋の南にいます。", nil, nil, 0x802a0775, 0xa9c77684, 0xb2eb4e2f, nil, nil, "...mm" },
  [98342] = { "大いなる猫の霊", "Stormrage Barrow DenからRelic of the Fang、Relic of the Claw、Relic of the Silent Shadowを取り戻し、Great Cat Spiritに返してください。", "我が精霊の力を引き出すには、言葉だけでは足りぬ。我が姿を理解し敬うには、狡猾さと、隠密と、そして追い詰められた時には獰猛さを体現できることを証明せねばならぬ。\n\nここから東のBarrow Densに、我が加護を宿した遺物が3つあり、そなたはそれを手に入れねばならぬ。それらは強大な怒れる精霊たちに守られ、奴らはそなたを見るなり襲いかかってくる。入り口の像が一時的な隠密の祝福を授け、奴らの間をすり抜けさせてくれよう。\n\nその遺物を我がもとへ持ち帰れ。そなたが我が姿をとる準備ができているか、見極めよう。", nil, nil, 0xb22fd0a9, 0x4c70cdf0, 0x6695208c, nil, nil, "...mm" },
  [98362] = { "Thunder Bluffへ", "Thunder Bluffへ戻り、Elder RiseにいるTurak Runetotemと話してください。", "再び別れの時が来た、若き者よ。学んだことを活かすため、そなたは自分を我がもとへ送った者のところへ戻るのだ。そなたの師、Turak Runetotemは、そなたという立派な弟子を得たようだ。我にもそう見える。彼の教えに耳を傾けよ。そうすれば、そなたはまもなくGreat Cat Spiritの力を引き出し、その姿をとれるようになろう。\n\n来た場所へ戻るがよい。時が来れば、また会おう。", nil, nil, 0xb1ea6f7d, 0x7484d02e, 0x42a21fd6, nil, nil, "...mm" },
  [98372] = { "不幸な最期", nil, nil, nil, nil, 0xc0c4b3d4, nil, nil, nil, nil, ".mmmm" },
  [98386] = { "Alther's Mill", "RedridgeにいるForeman Oslowのために、Alther's MillでGreater Tarantulaを$N1匹倒し、Tarantula Eggを$N2個壊してください。", "オーク、gnoll、murloc。何もかもが、この橋を期限までに仕上げるのを邪魔しようとしてるみたいだ。今度はうちの製材所にタランチュラがはびこってるって知らせが来た！\n\nもう少し稼ぐ気があるなら、東のAlther's Millへ行って、蜘蛛の問題を片づけてくれないか？ 安心して作業員を荷物の受け取りに行かせられないんじゃ、あそこは俺にとって役立たずも同然なんだ。\n\nああ、それと、Altherのじいさんに会ったら、奴の尻拭いをしてやったんだから貸しだって伝えてくれ。", nil, nil, 0xe7ba8f99, 0x7745e897, 0xebb117bb, nil, nil, "...mm" },
  [98387] = { "Blackrockの封鎖", "Stolen Weaponを$N1個とBlackrock Suppliesを$N2個、LakeshireのMarshal Marrisのところへ持って行って下さい。", "Blackrockのオークどもがわかっていないのは、これが消耗戦だということだ。奴らはAllianceの領土に図々しく押し入ったせいで無防備になり、物資もなく、周りの山から資源を集めるしかなくなっている。\n\n腹が減っていては軍は動けん、{name}。東のStonewatch Keepの南にある奴らの野営地へ行き、食料と武器を奪ってこい。飢えて無防備になったオークどもの闘志がどれほどのものか、見てやろうじゃないか。", nil, nil, 0xaf4ac457, 0x49a066b7, 0x365258cc, nil, nil, "..smm" },
  [98389] = { "闇の中の光", "DeathknellにいるAramis Hammerhandのために、Night's Web HollowでWebbed Victimを$N1人解放してください。", "ごきげんよう、{class}。そう、私はパラディンだ。死でさえも光を止めることはできない。\n\nこの点で、私のような者はすべてのForsakenと共通している。我々は、生者が自らの終わりとみなすものを乗り越えたのだ。だが、我々の仲間の中にさえ我々を恐れる者がいる。何かの化け物として我々に打ち倒されるのではないかと疑っているのだ。\n\n実のところ、我々とアンデッドであることとの関係は複雑だが、私は仲間を傷つけるためにここにいるのではない。そのことを他の者たちに示すのを手伝ってくれ。北西のNight's Web Hollowへ行き、そこで蜘蛛に捕らわれている、蘇ったばかりの愚か者たちを解放してくれ。", nil, nil, 0x1a235ca8, 0xb759528e, 0x17d83b11, nil, nil, "..smm" },
  [98391] = { "Sisterhood of Elune", "DarnassusのSister Aquinneと話してください。", "祝福を、{class}。Sisterhood of Eluneは何千年ものあいだ、kaldorei社会の柱として立ってきました。\n\nGreat Sunderingの前も、War of the Ancientsの前も、そしてLong Vigilのあいだも、私たちは闇の中で民を導き、癒やしてきました。それが私たちの務めであり、比類なきMother Moonの求めることなのです。\n\n今、極めて重要な件であなたの助けが必要です。Sister AquinneがDarnassusであなたの到着を待っています。", nil, nil, 0xbbe6a9b4, 0x1f3d24f5, 0xd260a541, nil, nil, "...mm" },
  [98392] = { "Gladeに潜む闇", "Oracle GladeのSentinel Arynia Cloudsbreakのために、Hatescreech's Amulet、Windmistress Gaedress' Amulet、Witchmother Arysa's Amuletを集めてください。", "このベルト……革をよく見てください、{name}。繊維に穢れが通っているのが見えますか？\n\nその出どころについては心当たりがありますが、確かめるにはさらなる証拠が必要です。\n\nもう一度西のハーピーの巣へ出向いて、その頭目たちを倒してください。彼女たちの首飾りにこのベルトと同じ闇が宿っていれば、答えが得られるでしょう。", nil, nil, 0xaad1e9ab, 0xab3da6db, 0x662c4561, nil, nil, "...mm" },
  [98393] = { "大いなる猫の霊", "MoongladeのNighthavenの村にいるDendrite Starblazeと話してください。", "あなたは旅の次の段階に進む準備ができたようですね、若きドルイドよ。Dendrite Starblazeがあなたを呼んでいて、もう一度Moongladeで彼を訪ねてほしいと願っています。\n\nMoongladeへ連れていってくれる魔法を呼び出す術はもう身につけていますから、望むならすぐにでも出発できるはずです。ドルイドの修行を続けたいのなら、早めに発つことをお勧めします。", nil, nil, 0xb22fd0a9, 0x127a78ca, 0xe8864144, nil, nil, "...mm" },
  [98394] = { "大いなる猫の霊", "Moonglade南部にいるGreat Cat Spiritを探し出し、猫の本質についてそれが語ることを学んでください。", "Moongladeの南部、橋を見下ろす丘に、私たちがGreat Cat Spiritと呼ぶ、賢く狡猾な存在が住んでいます。\n\nGreat Bear Spiritと同じように、この精霊は猫の姿をとりたいと願うドルイドたちの師であり導き手となってきました。すべてのドルイドはいずれその知恵を求めます。あなたも猫の姿をとりたいのなら、そうすることになるでしょう。\n\nGreat Cat Spiritに会いに行き、それが教えてくれることを学んできなさい。", nil, nil, 0xb22fd0a9, 0x75cdb0e3, 0x65936190, nil, nil, "...mm" },
  [98396] = { "大いなる猫の霊", "Stormrage Barrow DenからRelic of the Fang、Relic of the Claw、Relic of the Silent Shadowを取り戻し、Great Cat Spiritに返してください。", "我が精霊の力を引き出すには、言葉だけでは足りぬ。我が姿を理解し敬うには、狡猾さと、隠密と、そして追い詰められた時には獰猛さを体現できることを証明せねばならぬ。\n\nここから東のBarrow Densに、我が加護を宿した遺物が3つあり、そなたはそれを手に入れねばならぬ。それらは強大な怒れる精霊たちに守られ、奴らはそなたを見るなり襲いかかってくる。入り口の像が一時的な隠密の祝福を授け、奴らの間をすり抜けさせてくれよう。\n\nその遺物を我がもとへ持ち帰れ。そなたが我が姿をとる準備ができているか、見極めよう。", nil, nil, 0xb22fd0a9, 0x4c70cdf0, 0x6695208c, nil, nil, "...mm" },
  [98397] = { "Darnassusへ", "Darnassusへ戻り、Cenarion EnclaveにいるMathrengyl Bearwalkerと話してください。", "再び別れの時が来た、若き者よ。学んだことを活かすため、そなたは自分を我がもとへ送った者のところへ戻るのだ。そなたの師、Mathrengyl Bearwalkerは、そなたという立派な弟子を得たようだ。我にもそう見える。彼の教えに耳を傾けよ。そうすれば、そなたはまもなくGreat Cat Spiritの力を引き出し、その姿をとれるようになろう。\n\n来た場所へ戻るがよい。時が来れば、また会おう。", nil, nil, 0xcf1122f7, 0x17d4d4c5, 0xab87cae5, nil, nil, "...mm" },
  [98398] = { "Oracle Tree", "近くにあるOracle Tree Barkを見つけ、そのメッセージを受け取ってください。", "これほど短い間にあなたがここで成し遂げたことには感心しました、{name}。ここに残って私の務めを手伝ってほしいと頼めたらよいのですが……もっと大きな務めがあなたを待っていることは、心の中でわかっています。\n\nOracle Treeがちょうど樹皮の一片を落としたのに気づきました。きっと果たしてほしい務めがあるのでしょう。話しかけてみるとよいですよ。", nil, nil, 0x9c6398c9, 0xc836cbe1, 0x5c5a347c, nil, nil, "...mm" },
  [98403] = { "歪んだ憎悪", "Befouled Webwoodを$N1匹倒し、Xethorr the WickedのMature Fel MossをDolanaarにいるTallonkai Swiftrootのところへ持って行ってください。", "Lord Melenasはひとりで動いていたのではありません。別の者の命を受けていたのです。あなたが追うべきはXethorr the Wickedです。どうやら彼は、Teldrassilを住処とする蜘蛛たちをねじ曲げ、その毒を何か邪悪な企みに使うつもりのようです。\n\n彼は森の奥深く、ここから北西のCleftと呼ばれる場所に居を構えています。用心して、仲間を連れて行きなさい。Xethorrは侮ってよい相手ではありません。\n\n彼の眷属を始末し、このsatyrがここで何をしているのか、もっとわかりそうなものを何でも持ってきてください。", nil, nil, 0x10738b8e, 0xa891e626, 0x8a01b9a3, nil, nil, "...mm" },
  [98404] = { "大いなるWindborneの猫の霊", "Stormrage Barrow DenからRelic of the Fang、Relic of the Claw、Relic of the Silent Shadowを取り戻し、Avatar of Saeyleenanに返してください。", "我が精霊の力を引き出すには、試練を受けねばならぬ。我が姿を理解し敬うには、狡猾さと、隠密と、そして追い詰められた時には獰猛さを体現できることを証明せねばならぬ。\n\nここから東のBarrow Densに、そなたが手に入れねばならぬ遺物が3つある。それらは強大な怒れる精霊たちに守られ、奴らはそなたを見るなり襲いかかってくる。入り口の像が一時的な隠密の祝福を授け、奴らの間をすり抜けさせてくれよう。\n\nこの地のドルイドの試練に合格するため、その遺物を我がもとへ持ち帰れ。", nil, nil, 0x802a0775, 0xda3dcaa5, 0x9983bb04, nil, nil, "..smm" },
  [98405] = { "大いなる猫の霊", "Moonglade南部にいるGreat Cat Spiritを探し出し、猫の本質についてそれが語ることを学んでください。", "Moongladeの南部、橋を見下ろす丘に、私たちがGreat Cat Spiritと呼ぶ、賢く狡猾な存在が住んでいます。\n\nGreat Bear Spiritと同じように、この精霊は猫の姿をとりたいと願うドルイドたちの師であり導き手となってきました。すべてのドルイドはいずれその知恵を求めます。あなたも猫の姿をとりたいのなら、そうすることになるでしょう。\n\nGreat Cat Spiritに会いに行き、それが教えてくれることを学んできなさい。", nil, nil, 0xb22fd0a9, 0x75cdb0e3, 0x65936190, nil, nil, "...mm" },
  [98407] = { "力の誇示", "Lakeshire近くにいるDeputy Feldonのために、Redridge ThrasherからSpiked Collarを$N1個集めて下さい。", "gnollどもが人間のこんな近くに野営するほど大胆になっているなら、どこまで踏み込んでくるかわからん。奴らを思いとどまらせる必要がある。\n\nあの獣どもはろくに統率も取れていないが、何よりも力を重んじるようだ。最も手強い奴らを倒して戦利品をいくらか奪えれば、奴らがなぜ本来いるべき丘に引っ込んでいるべきなのか、思い出させてやれる。\n\n奴らのthrasherを見かけたら、その首輪を持ってこい。それでAllianceへの恐れを再び奴らに叩き込めるはずだ。", nil, nil, 0xaf8e550f, 0xed3fd63d, 0x0a358c18, nil, nil, "...mm" },
  [98417] = { "復讐の足跡", "Maseara Autumnmoonは、Forest Songの西、Satyrnaarの悪魔たちの間を探してほしいと言っています。戻ったら、彼女の夫Kurothelの手がかりを報告して下さい。", nil, nil, nil, 0x6e03cfc5, 0xb0601dd3, nil, nil, nil, "..mmm" },
  [98418] = { "分かち合う怒り", "Xavian Rogueを$N1体、Felswornを$N2体、Betrayerを$N3体、Hellcallerを$N4体倒して下さい。\nその後、Forest SongのMaseara Autumnmoonのところへ戻って下さい。", nil, nil, nil, 0xb918ae35, 0xd218f83f, nil, nil, nil, "..mmm" },
  [98423] = { "Treaty of Understanding", "Treaty of UnderstandingをIronforgeのMagni Bronzebeardに届けてください。", "地下室の中で、BronzebeardとWildhammerのドワーフの氏族の間で結ばれた和平条約の条項を記した石板を見つける。War of the Three Hammersの直後の時代のもののようで、ドワーフの歴史の中でもきわめて重要な品である可能性が高い。Ironforgeの王なら、きっとこの遺物に興味を持つだろう。", nil, nil, 0xf42ec125, 0x9c2002f0, 0x00b00d52, nil, nil, "..smm" },
  [98424] = { "Fizsprocketのメモ", "The Venture Co. Mineの中でSupervisor Fizsprocketの残りのページを集め、Bloodhoof Village付近にいるMorin Cloudstalkerに届けてください。", "特に擦り切れた書類が、Fizsprocketの胸の内ポケットに、ほかとは別に折りたたんでしまわれている。\n\nVenture Co.とこの地域での奴らの活動に対抗するのに使えそうな、重要な情報が書かれているようだ。Morin Cloudstalkerのもとへ戻る前に、もっと探してみるのが賢明だろう。", nil, nil, 0x6d5edb74, 0xc344e88c, 0x4ea62c19, nil, nil, "...mm" },
  [98427] = { "操業停止", "Clearcutter KeyをBloodhoof Villageの外にいるMorin Cloudstalkerに届けてください。", "書類のひとつに書かれているshredder……あれは旅の途中で見たことがあります。手と斧でやるのに比べて、ほんのわずかな時間で森を壊滅させてしまうのです。\n\nEarth Motherの子らが何千年も住処としてきた林がまるごと……ほんの数日で消し去られるのです。\n\n私たちの子供たちが最初の一歩を踏み出す場所から目と鼻の先にある、私たちの故郷で、そんなことが起きるのを許しはしません。\n\n{name}、どうか仲間を集め、北東の鉱山へもう一度入って、それがもう一本たりとも木を切り倒さないようにしてください。", nil, nil, 0x63bcfc2d, 0x1c4f7bfc, 0x53f56d0c, nil, nil, "..smm" },
  [98430] = { "Longwalkers", "Perith StormhoofがPalemane Rockから脱出するのを手助けし、彼の無事をThunder BluffのCairne Bloodhoofに報告してください。", "ようこそ、{class}。こんなに暗く荒々しい場所の奥深くまで、何の用で来たのですか？\n\n私はHigh Chieftain Cairne Bloodhoofにここへ遣わされました。住みついたgnollたちと意思を通わせる取り組みの一環としてです。任務の残りは秘密にしておかねばなりません。族長の信頼厚き斥候、Longwalkersに関わることはすべてそうなのです。\n\nあなたが知るべきことはただひとつ、私たちの外交は暴力で迎えられたということです。あなたが逃げる手助けをしてくれなければ、私は今夜のgnollたちのご馳走になってしまうかもしれません。\n\n引き受けてくれますか？", nil, nil, 0xe9313160, 0x5e46e8f2, 0x231a04dd, nil, nil, "...mm" },
  [98435] = { "Thunderhorn's Report", "Thunderhorn's ReportをThunder BluffのArch Druid Hamuul Runetotemに届けてください。", "あなたの助けのおかげでここで成し遂げた進展を、Thunder Bluffの長老たちに知らせなければなりません。\n\nどうか、これをThunder BluffのArch Druid Hamuul Runetotemのもとへ届けてください。彼は街の東側のElder Riseにいます。街の中心までリフトで上がり、それから橋を渡ってそこへ行かなければなりません。", nil, nil, 0x84555a75, 0x39ea52d2, 0xbfc7c379, nil, nil, "...mm" },
  [98447] = { "Valor家", "DarkshireのSirra Von'Indiのために、Raven HillのValor家の幽霊の原因を突き止めて下さい。", "あなたがValor家の幽霊たちを倒したにもかかわらず、襲撃の報告は止んでいません。良い賭けではありましたが、結局のところ、彼らの心残りを晴らしてはいなかったのかもしれません。\n\n私の調べでは、この一家は全員が同時に行方不明になったようです。彼らの魂をこの世に縛りつけることになった惨事が何であれ、それは一度に起きたに違いありません。\n\n唯一の手がかりは、あなたがあの本を見つけた場所です。Raven Hillへ戻り、何か見つからないか調べてください。彼らの武器を持っていけば、何かが呼び起こされるかもしれません。", nil, nil, 0x27a57039, 0x5a0bdeb9, 0x839ba7ea, nil, nil, "...mm" },
  [98459] = { "美徳の欠如", "Tom's GiftをWetlandsのMenethil HarborにいるBart Tidewaterに届けてください。", "Bart Tidewaterは、ろくでもないケチ野郎なんだよ！\n\n「Maiden's Virtueの船長」だなんて名乗ってやがる。あの船はTanarisの岩場までしか航海したことがないんだぞ！ あいつは船長なんかじゃない、ポーカーで勝ちまくってそもそもVirtueを買えただけの役者なんだ！\n\nWetlandsのMenethil Harborに行くことがあったら、これをあいつに渡して、Half-fishのじいさんからだって伝えてくれ。\n\nところで、ここから港まで直接連れていってくれる船があるぞ。二番目の寄港地だ！\n\nそれに、あいつはポーカーでイカサマするんだ！", nil, nil, 0x7df3b255, 0x8476eeda, 0xd2b7c232, nil, nil, "...mm" },
  [98461] = { "報われぬ愛", "Hollee's NoteをWetlandsのMenethil Harbor付近にいるTarrel Rockweaverに届けてください。", "Auberdineを出るなら、ちょっと手を貸してほしいの！\n\n大切な友達のTarrelと私は学校の同級生だったの。ああ、彼は発掘のことなら何でも頭の回転が速くてね！ 卒業後に離ればなれになっちゃって……彼はWetlandsへ、私はここDarkshoreへ。\n\n<Holleeはため息をつき、それから少し眉をひそめる。>\n\nごめんなさい、それと彼の奥さん……Merrinもね。\n\nまあ、どうでもいいわ。Wetlandsに行くなら、彼が無事か確かめてくれる？ それと、これを渡してもらえるかしら？ たぶんMenethil Harborの近くにいるはずよ。そこへ直行する船があるわ。", nil, nil, 0xb2150b23, 0x7208db43, 0xa9ab1ed6, nil, nil, "...mm" },
  [98463] = { "町の噂", "StranglethornのBooty BayにあるSalty Sailor TavernのNixxrax Fillamugを訪ねて下さい。", nil, nil, nil, 0xb19809e8, 0xe99b857b, nil, nil, nil, "..mmm" },
  [98512] = { "Al'Akethの暗殺者", "Shen'dar HighlandsでAl'Aketh Assassinsを10体倒してください。", "そこのよそ者、身を低くして静かにしろ。ここにいるのは我々だけではない。\n\n国境付近を巡回していたら、北の丘を上がったところにある家の周りを、Al'Akethの連中が何人もうろついているのに気づいた。何をしているのかはわからんが、ろくなことではあるまい。\n\n役に立ちたいなら、中へ入って奴らを片づけろ。私はここで待って、背中を見張っていてやる。", nil, nil, 0xa0048cb3, 0xec0e36e9, 0x7e911b38, nil, nil, "...mm" },
  [98517] = { "火の呼び声", "シャーマンとしての修行を続けるため、Zephras IsleのSessaria SkystrideかAarnor Galestrikeに報告してください。\n\nZephrasへは、Thunder Bluffの北西、MulgoreのSkywatcher Plateauに停泊するスカイカッター便で戻ることができます。", "ごきげんよう、若きSkyborneよ。精霊たちがそなたのことを語り、そなたが火の呼び声に応える用意ができていると告げている。だが、そなたをその道へと導くのは我ではない。精霊界にあるそなたの故郷へ戻り、そこで師たちを訪ねるがよい。何をなすべきか、彼らが教えてくれるであろう。", nil, nil, 0x53f3b76b, 0xe2cf2544, 0x04034459, nil, nil, "...mm" },
  [98545] = { "Leonidの手紙", "Sealed LetterをUndercityのGlix Xizzixに届けてください。", "せっかく来たのだから、この手紙をUndercityにいる私の古い友人に届けてもらいたい。自分で届けたいところだが、私はDark Ladyといささか色々とあった身でね、中立の第三者に届けてもらったほうがいいのだ。\n\n探してほしいのは、UndercityのTrade Quarterにいる、Glix Xizzixという名のゴブリンだ。きっと喜んで君の手間に報いてくれるだろう。\n\n<Leonidは手紙を渡しながら、低く含み笑いをする。>", nil, nil, 0x641cb3cb, 0xd4d899ce, 0xd58664de, nil, nil, "...mm" },
  [98574] = { "Hallowed Memorandum", "Hallowed Memorandumを読み、AnvilmarのBranstock Khalderと話してください。", "あんたが手伝ってくれてる間に、この覚え書きをあんたに渡すよう預かったんだ。時間がある時に読んでみてくれ。プリーストのトレーナーのBranstockから来たものだと思うんだがな。目を通したら、手が空いた時にAnvilmarの中にいる彼を訪ねてくれ。", nil, nil, 0x9246c933, 0x9ede68c6, 0xd8ec11c1, nil, nil, "...mm" },
  [98575] = { "Tainted Tablet", "Tainted Tabletを読み、Valley of TrialsのDenの中にいるNartokと話してください。", "ああ、あなたがいない間に、あなた宛ての石板が届きましたよ、{name}。\n\n私はなるべくウォーロックとは関わらないようにしているのですが、時間がある時に読んでみた方がいいと思います。私の思い違いでなければ、新しくあなたのトレーナーになったNartokから来たものです。準備ができたら、彼があなたと話したいそうですよ。", nil, nil, 0x918917d0, 0xced995c4, 0xea3fd096, nil, nil, "...mm" },
  [98576] = { "Glyphic Parchment", "Glyphic Parchmentを読み、Valley of TrialsのDenの入口近くにいるMai'ahと話してください。", "ああ、あなたがいない間に、あなた宛ての羊皮紙が届きましたよ、{name}。\n\n時間がある時に読んでみてください。私の思い違いでなければ、メイジのトレーナーのMai'ahから来たものです。準備ができたら、彼女があなたと話したいそうですよ。", nil, nil, 0x6fd02ac3, 0x38596371, 0x047cc841, nil, nil, "...mm" },
  [98581] = { "Archaic Rune", "Archaic Runeを読み、AnvilmarのTeo Hammerstormと話してください。", "あんたが手伝ってくれてる間に、このルーンをあんたに渡すよう預かったんだ。時間がある時に読んでみてくれ。刻まれた文字のWildhammer風の作りからして、シャーマンのトレーナーのTeo Hammerstormから来たものだと思うんだがな。目を通したら、手が空いた時にAnvilmarの中にいる彼を訪ねてくれ。", nil, nil, 0x31d52645, 0x2d3d009b, 0x219621d8, nil, nil, "...mm" },
  [98601] = { "困難な道", "Consecrated Scrollを読み、Deathknellの教会にいるAramis Hammerhandと話してください。", "お前が心なきScourgeの相手をしている間に、この巻物がお前宛てに届いた。光の匂いがぷんぷんするから、お前のようなパラディンにとっては何か重要なものなんだろう。\n\nまた出かける前に読んでおけ。ただ頼むから……読む時は離れてくれ。パラディンはどうも落ち着かないんでな。", nil, nil, 0x53ba5fc8, 0xba081fbb, 0x14a4ef8e, nil, nil, "..smm" },
  [98731] = { "Great Cat Spiritの祝福", nil, "私の祝福を受けたのですから、Dendriteのもとへ戻りなさい。彼がさらに教えてくれるでしょう。いつかまた会えることを願っています。\n\n影が永遠にあなたを隠し、あなたの敵がたやすくその爪の餌食となりますように、若き者よ。", nil, nil, 0x063c07d4, nil, 0xbef78e20, nil, nil, ".m.mm" },
  [98738] = { "Great Windborne Cat Spiritの祝福", nil, "私の祝福を受けたのですから、Dendriteのもとへ戻りなさい。彼がさらに教えてくれるでしょう。\n\n残念ながら、今のところあなたに教えられることはほとんど残っていません。いつかまたZephrasの私のもとを訪ねてくれることを願っています。あなたには見込みを感じますよ、若きshen'doreiよ。\n\n影が永遠にあなたを隠し、あなたの敵がたやすくその爪の餌食となり、風があなたの歩みを導きますように。", nil, nil, 0x823a61f5, nil, 0x27a843d1, nil, nil, ".m.mm" },
  [98739] = { "Great Cat Spiritの祝福", "Dendriteと話してください。", "私の祝福を受けたのですから、Dendriteのもとへ戻りなさい。彼がさらに教えてくれるでしょう。いつかまた会えることを願っています。\n\n影が永遠にあなたを隠し、あなたの敵がたやすくその爪の餌食となりますように、若き者よ。", nil, nil, 0x063c07d4, 0x5d7ff8e0, 0xbef78e20, nil, nil, "...mm" },
  [98815] = { "Highlandの皮", "Thicket Raptor Hideを$N1枚、Menethil Harborの皮なめし職人James Halloranのところへ届けて下さい。", nil, nil, nil, 0xef33826c, 0x2ade49d5, nil, nil, nil, "..mmm" },
  [98823] = { "大地の残響", "Titan Relicを、Mulgore北西のSkywatcher PlateauにいるMuln Earthfuryのところへ持って行って下さい。", nil, nil, nil, 0xd4e1512d, 0x67b36d12, nil, nil, nil, "..mmm" },
  [98824] = { "太古のプリズム", "Titan Relicを、IronforgeのHall of ExplorersにいるHigh Explorer Magellasのところへ持って行って下さい。", nil, nil, nil, 0xe4e83006, 0xdf91b989, nil, nil, nil, "..mmm" },
  [98887] = { "Darkspear Islandsでの争い", "Darkspear Islands Marks of Honorを3個、戦場の外にいるHorde Warbringerのところへ持って行って下さい。", nil, nil, nil, 0x969b71fe, 0xeba00ea0, nil, nil, nil, "..mmm" },
  [98895] = { "Darkspear Islandsの衝突", "Darkspear Islands Marks of Honorを3個、戦場の外にいるAlliance Brigadier Generalのところへ持って行って下さい。", nil, nil, nil, 0xce4159d8, 0x5c451deb, nil, nil, nil, "..mmm" },
  [98903] = { "Darkspear Islandsをめぐる戦い！", "Darkspear Islandsの戦場で勝利し、Northwatch HoldのBrelinda McFarryのところへ戻って下さい。", nil, nil, nil, 0x50c64cd8, 0x2ac07de6, nil, nil, nil, "..mmm" },
